<?php

declare(strict_types=1);

use PayLens\Core\Database;
use PayLens\Core\Schema;

/**
 * Anomalies, notifications and documents.
 *
 * Anomalies are generated by comparing payroll records against expected
 * rules (a duplicate payment, an unusual jump). They are stored so an
 * investigator can work a case over time.
 */
return [
    'up' => static function (Database $db): void {
        (new Schema($db, 'anomalies'))
            ->string('id', 32)
            ->string('type', 40)
            ->string('severity', 16, false, 'low')
            ->string('status', 16, false, 'open')
            ->string('employee_id', 32, true)
            ->string('payroll_run_id', 32, true)
            ->string('title', 160)
            ->text('description')
            ->int('risk_score', false, 0)
            ->bigInt('amount_paise', true)
            ->string('assigned_to', 120, true)
            ->dateTime('detected_at')
            ->dateTime('created_at')
            ->dateTime('updated_at')
            ->primary('id')
            ->index('status')
            ->index('severity')
            ->index('employee_id')
            ->foreignKey('employee_id', 'employees', 'id', 'SET NULL')
            ->create();

        (new Schema($db, 'notifications'))
            ->string('id', 32)
            ->bigInt('user_id', true)
            ->string('type', 16, false, 'info')
            ->string('category', 24, false, 'system')
            ->string('title', 160)
            ->text('description')
            ->string('action_label', 80, true)
            ->string('action_href', 160, true)
            ->string('severity', 16, true)
            ->dateTime('read_at', true)
            ->dateTime('created_at')
            ->primary('id')
            ->index('user_id')
            ->index('category')
            ->foreignKey('user_id', 'users', 'id', 'CASCADE')
            ->create();

        (new Schema($db, 'documents'))
            ->string('id', 32)
            ->string('employee_id', 32)
            ->string('name', 160)
            ->string('type', 64)
            ->string('status', 24, false, 'verified')
            ->date('issued_at', true)
            ->date('expires_at', true)
            ->int('size_bytes', false, 0)
            ->dateTime('created_at')
            ->primary('id')
            ->index('employee_id')
            ->index('type')
            ->foreignKey('employee_id', 'employees', 'id', 'CASCADE')
            ->create();
    },
];
